export const laConsoleArticles5Security: SubSection[] = [{"id":"laconsole-qu-est-ce-qu-un-cookie","title":"Qu'est-ce qu'un Cookie ?","blocks":[{"type":"note","variant":"info","title":"Source","text":"Qu'est-ce qu'un Cookie ? - laConsole.pdf - 8 pages intégrées depuis laConsole.dev."},{"type":"h","text":"Page 1"},{"type":"p","text":"Qu'est-ce qu'un Cookie ? - laConsole 02/03/2025 09 : 37"},{"type":"p","text":"TOP raccourcis Emmet"},{"type":"p","text":"HOT"},{"type":"h","text":"Qu'est-ce qu'un Cookie ?"},{"type":"p","text":"Omniprésents sur le web, les cookies sont aujourd'hui utilisés"},{"type":"p","text":"pour faciliter le stockage et l'échange d'informations entre"},{"type":"p","text":"pages et sites."},{"type":"p","text":"⏾"},{"type":"p","text":"août 2022 3 min"},{"type":"p","text":"# #"},{"type":"p","text":"culture web data"},{"type":"p","text":"Inscription à la"},{"type":"p","text":"NEWSLETTER"},{"type":"h","text":"C’est quoi un cookie ?"},{"type":"p","text":"Les cookies sont de petits fichiers textuels permettant de"},{"type":"p","text":"stocker dans un navigateur des données de l’utilisateur,"},{"type":"p","text":"relatives aux pages d’un domaine web. Ils sont définis par :"},{"type":"p","text":"Un nom (identifiant)"},{"type":"p","text":"Une valeur (la donnée à stocker)"},{"type":"p","text":"Une date d’expiration"},{"type":"p","text":"Ces cookies peuvent être manipulés par l’intermédiaire"},{"type":"p","text":"d’un langage de programmation web tel que JavaScript."},{"type":"p","text":"https://laconsole.dev/blog/cookies Page 1 sur 8"},{"type":"image","src":"images/laconsole-articles-5/qu-est-ce-qu-un-cookie-laconsole-p001.jpg","alt":"Page originale de Qu'est-ce qu'un Cookie ? - laConsole.pdf - page 1"},{"type":"h","text":"Page 2"},{"type":"p","text":"Qu'est-ce qu'un Cookie ? - laConsole 02/03/2025 09 : 37"},{"type":"h","text":"Newsletter"},{"type":"p","text":"Inscrivez-vous pour recevoir"},{"type":"p","text":"chaque mois du contenu"},{"type":"p","text":"100% dev web ! #nospam"},{"type":"p","text":"S'inscrire"},{"type":"p","text":"KevCod3ur64@mail.com"},{"type":"p","text":"Quiz News Ressources"},{"type":"h","text":"Rôle des cookies"},{"type":"p","text":"À chaque nouvelle requête HTTP d’un navigateur vers un"},{"type":"p","text":"serveur web (autrement dit chargement de page), la"},{"type":"p","text":"connexion est interrompue et le serveur oublie tout ce qui"},{"type":"p","text":"concernait l’utilisateur . Cela s’avère bien souvent gênant"},{"type":"p","text":"lorsqu’il s’agit d’exploiter des informations sur un"},{"type":"p","text":"ensemble de pages d’un site web. Grâce aux cookies, il va"},{"type":"p","text":"pouvoir être possible de stocker des informations"},{"type":"p","text":"concernant un utilisateur au sein du navigateur pour y"},{"type":"p","text":"accéder ltérieurement, et ce, depuis n’importe quelle page."},{"type":"h","text":"Formations"},{"type":"h","text":"gratuites"},{"type":"p","text":"Découvrir"},{"type":"p","text":"Formez-vous au dev web avec 20+"},{"type":"p","text":"formations 100% gratuites ."},{"type":"p","text":"Les cookies développent alors un potentiel très intéressant"},{"type":"p","text":"tant pour les possibilités d’ usage pour les développeurs"},{"type":"p","text":"https://laconsole.dev/blog/cookies Page 2 sur 8"},{"type":"image","src":"images/laconsole-articles-5/qu-est-ce-qu-un-cookie-laconsole-p002.jpg","alt":"Page originale de Qu'est-ce qu'un Cookie ? - laConsole.pdf - page 2"},{"type":"h","text":"Page 3"},{"type":"p","text":"Qu'est-ce qu'un Cookie ? - laConsole 02/03/2025 09 : 37"},{"type":"p","text":"que pour l’expérience utilisateur des visiteurs. Ils"},{"type":"p","text":"fournissent une sorte de mémoire pour les pages web."},{"type":"p","text":"Ainsi, dès qu’un utilisateur connu demande à accéder à une"},{"type":"p","text":"page d’un site web, les cookies vont également"},{"type":"p","text":"automatiquement être envoyés dans la requête de"},{"type":"p","text":"l’utilisateur . Cela va nous permettre de lui proposer une"},{"type":"p","text":"expérience personnalisée sur le site web (produits"},{"type":"p","text":"personnalisés, publicités personnalisées, interface"},{"type":"p","text":"personnalisée, etc.)."},{"type":"p","text":"Si les cookies sont tant controversés, ce n’est pas tant pour"},{"type":"p","text":"ce qu’ils sont, mais bien pour l’utilisation qui en est faite. Si"},{"type":"p","text":"cette technologie est très utile pour améliorer l’expérience"},{"type":"p","text":"utilisateur, elle peut aussi être utilisée à des fins de"},{"type":"code","filename":"page-3-exemple-1","language":"javascript","code":"#rgpd #cnil"},{"type":"p","text":"manipulation de l’expérience web."},{"type":"p","text":"De plus, les cookies étant accessibles dans le navigateur, il"},{"type":"p","text":"est important de ne pas y stocker d’informations"},{"type":"p","text":"confidentielles comme des mots de passe par exemple."},{"type":"p","text":"Il est impossible de savoir si des cookies vous"},{"type":"p","text":"profitent ou profitent à une autre partie. Il est donc"},{"type":"p","text":"important de se fier au site web que vous visitez"},{"type":"p","text":"#"},{"type":"p","text":"pour savoir comment il utilise les cookies et lire sa"},{"type":"p","text":"politique de cookies et/ou sa politique de"},{"type":"p","text":"confidentialité ."},{"type":"p","text":"https://laconsole.dev/blog/cookies Page 3 sur 8"},{"type":"image","src":"images/laconsole-articles-5/qu-est-ce-qu-un-cookie-laconsole-p003.jpg","alt":"Page originale de Qu'est-ce qu'un Cookie ? - laConsole.pdf - page 3"},{"type":"h","text":"Page 4"},{"type":"p","text":"Qu'est-ce qu'un Cookie ? - laConsole 02/03/2025 09 : 37"},{"type":"h","text":"Newsletter"},{"type":"p","text":"Inscrivez-vous pour recevoir"},{"type":"p","text":"chaque mois du contenu"},{"type":"p","text":"100% dev web ! #nospam"},{"type":"p","text":"S'inscrire"},{"type":"p","text":"KevCod3ur64@mail.com"},{"type":"p","text":"Quiz News Ressources"},{"type":"h","text":"2 grands types de"},{"type":"h","text":"cookies"},{"type":"p","text":"On distingue les cookies en 2 grandes familles, selon leur"},{"type":"p","text":"domaine d’accessibilité ."},{"type":"h","text":"Cookies « internes » ou « first-"},{"type":"h","text":"party »"},{"type":"h","text":"Formations"},{"type":"h","text":"gratuites"},{"type":"p","text":"Découvrir"},{"type":"p","text":"Formez-vous au dev web avec 20+"},{"type":"p","text":"formations 100% gratuites ."},{"type":"p","text":"Les cookies internes sont définis par un site sur son propre"},{"type":"p","text":"nom de domaine . Ils peuvent être nécessaires pour le bon"},{"type":"p","text":"fonctionnement du site ou facultatifs."},{"type":"p","text":"https://laconsole.dev/blog/cookies Page 4 sur 8"},{"type":"image","src":"images/laconsole-articles-5/qu-est-ce-qu-un-cookie-laconsole-p004.jpg","alt":"Page originale de Qu'est-ce qu'un Cookie ? - laConsole.pdf - page 4"},{"type":"h","text":"Page 5"},{"type":"p","text":"Qu'est-ce qu'un Cookie ? - laConsole 02/03/2025 09 : 37"},{"type":"p","text":"Rôle"},{"type":"p","text":"Ils peuvent être déposés pour le bon fonctionnement du"},{"type":"p","text":"site, collecter des données personnelles, personnaliser"},{"type":"p","text":"l’expérience utilisateur, suivre le comportement de"},{"type":"p","text":"l’utilisateur, réaliser des statistiques ou encore servir à"},{"type":"p","text":"des fin publicitaires ."},{"type":"p","text":"Consentement"},{"type":"p","text":"Ils requièrent ou non le consentement de la part de"},{"type":"p","text":"l’utilisateur, selon leur rôle."},{"type":"p","text":"Exemples :"},{"type":"p","text":"Formations Ressources Blog"},{"type":"p","text":"laVeilleuse"},{"type":"p","text":"FREE"},{"type":"p","text":"Faciliter l’authentification"},{"type":"p","text":""},{"type":"p","text":"SOMMAIRE"},{"type":"p","text":"Sauvegarder un panier e-commerce"},{"type":"p","text":"Adapter l’apparence du site web (thème clair /"},{"type":"p","text":"C’est quoi un cookie ?"},{"type":"p","text":"sombre)"},{"type":"p","text":"Rôle des cookies"},{"type":"p","text":"2 grands types de cookies"},{"type":"p","text":"Etc."},{"type":"p","text":"Cookies « internes » ou « first-"},{"type":"p","text":"party »"},{"type":"p","text":"Cookies « tiers » ou « third"},{"type":"h","text":"Cookies « tiers » ou « third"},{"type":"p","text":"party »"},{"type":"h","text":"party »"},{"type":"p","text":"Les cookies tiers sont définis par un site sur le nom de"},{"type":"p","text":"domaine d’autre autre site (souvent une régie publicitaire)."},{"type":"p","text":"Les cookies sont généralement placés dans un site web via"},{"type":"p","text":"des scripts ou des balises ajoutés dans la page web. Ils"},{"type":"p","text":"sont entièrement facultatifs pour le bon fonctionnement du"},{"type":"p","text":"site."},{"type":"p","text":"Rôle"},{"type":"p","text":"https://laconsole.dev/blog/cookies Page 5 sur 8"},{"type":"image","src":"images/laconsole-articles-5/qu-est-ce-qu-un-cookie-laconsole-p005.jpg","alt":"Page originale de Qu'est-ce qu'un Cookie ? - laConsole.pdf - page 5"},{"type":"h","text":"Page 6"},{"type":"p","text":"Qu'est-ce qu'un Cookie ? - laConsole 02/03/2025 09 : 37"},{"type":"p","text":"Ils sont principalement déposés pour réaliser des"},{"type":"p","text":"statistiques ou encore servir à des fins publicitaires ."},{"type":"p","text":"Cela leur permet de collecter des informations de"},{"type":"p","text":"navigation pour établir un « profil comportemental » de"},{"type":"p","text":"l’utilisateur, qui peut ensuite être utilisé pour les cibler"},{"type":"p","text":"avec des annonces en ligne basées sur leurs intérêts «"},{"type":"p","text":"calculés »."},{"type":"p","text":"Consentement"},{"type":"p","text":"Ils requièrent le consentement de la part de l’utilisateur."},{"type":"p","text":"Exemples :"},{"type":"p","text":"Boutons de partage / like Facebook"},{"type":"p","text":"Intégration vidéo YouTube"},{"type":"p","text":"Tracking analytics (statistiques)"},{"type":"p","text":"Etc."},{"type":"p","text":"L’utilisation de cookies à des fins publicitaires est"},{"type":"p","text":"souvent perçue comme intrusive et portant"},{"type":"p","text":"atteinte à la vie privée. Cette activité est en partie"},{"type":"p","text":"#"},{"type":"p","text":"responsable de l’élaboration de nouvelles lois sur"},{"type":"p","text":"la protection de la vie privée, en particulier la loi"},{"type":"p","text":"européenne sur les cookies ou RGPD ."},{"type":"p","text":"https://laconsole.dev/blog/cookies Page 6 sur 8"},{"type":"image","src":"images/laconsole-articles-5/qu-est-ce-qu-un-cookie-laconsole-p006.jpg","alt":"Page originale de Qu'est-ce qu'un Cookie ? - laConsole.pdf - page 6"},{"type":"h","text":"Page 7"},{"type":"p","text":"Qu'est-ce qu'un Cookie ? - laConsole 02/03/2025 09 : 37"},{"type":"p","text":"Thibaud d'Arros"},{"type":"p","text":"Fondateur Développeur"},{"type":"p","text":"● ●"},{"type":"p","text":"Formateur"},{"type":"p","text":"●"},{"type":"p","text":"&"},{"type":"p","text":"L"},{"type":"p","text":"Enfant, je passais des heures à"},{"type":"p","text":"'"},{"type":"p","text":"A"},{"type":"p","text":"U"},{"type":"p","text":"remodeler le monde avec des"},{"type":"p","text":"@"},{"type":"p","text":"T"},{"type":"p","text":"LEGO. Plus tard, je découvre le"},{"type":"p","text":"E"},{"type":"p","text":"U"},{"type":"p","text":"dev, des LEGO où les briques"},{"type":"p","text":"R"},{"type":"p","text":"sont remplacées par des lignes"},{"type":"p","text":""},{"type":"p","text":"de code. J'en fais mon métier"},{"type":"p","text":"puis je décide de transmettre"},{"type":"p","text":"cette passion en école de dev et"},{"type":"p","text":"sur laConsole."},{"type":"h","text":"Lire aussi"},{"type":"p","text":"Comprendre"},{"type":"p","text":"TOP 30 des"},{"type":"p","text":"Que le Cryptage"},{"type":"p","text":"Frameworks"},{"type":"p","text":"signifie :"},{"type":"p","text":"à"},{"type":"p","text":"l'Extension Chiffrement,"},{"type":"p","text":"Apprendre"},{"type":"p","text":".io ? Hachage &"},{"type":"p","text":"en 2025"},{"type":"p","text":"Salage"},{"type":"p","text":"programmation culture web sécurité"},{"type":"p","text":"culture web hébergement data"},{"type":"p","text":"https://laconsole.dev/blog/cookies Page 7 sur 8"},{"type":"image","src":"images/laconsole-articles-5/qu-est-ce-qu-un-cookie-laconsole-p007.jpg","alt":"Page originale de Qu'est-ce qu'un Cookie ? - laConsole.pdf - page 7"},{"type":"h","text":"Page 8"},{"type":"p","text":"Qu'est-ce qu'un Cookie ? - laConsole 02/03/2025 09 : 37"},{"type":"p","text":"E-LEARNING COMMUNAUTÉ LÉGAL"},{"type":"p","text":"Formations Ressources Mentions"},{"type":"p","text":"laConsole, plateforme d'e-learning dédiée au"},{"type":"p","text":"légales"},{"type":"p","text":"Cheatsheets A propos"},{"type":"p","text":"développement web."},{"type":"p","text":"Politique de"},{"type":"p","text":"Blog Contact"},{"type":"p","text":"M'abonner à la newsletter"},{"type":"p","text":"confidentialité"},{"type":"p","text":"Faire ma veille"},{"type":"p","text":"status : 200 laConsole © 2025"},{"type":"p","text":"https://laconsole.dev/blog/cookies Page 8 sur 8"},{"type":"image","src":"images/laconsole-articles-5/qu-est-ce-qu-un-cookie-laconsole-p008.jpg","alt":"Page originale de Qu'est-ce qu'un Cookie ? - laConsole.pdf - page 8"}]}];

